class Solution {
    public boolean canCross(int[] stones) {
        java.util.Map<Integer, java.util.Set<Integer>> map = new java.util.HashMap<>();
        for (int s : stones) map.put(s, new java.util.HashSet<>());
        map.get(0).add(0);
        for (int s : stones) {
            for (int k : map.get(s)) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step > 0 && map.containsKey(s + step)) {
                        map.get(s + step).add(step);
                    }
                }
            }
        }
        return !map.get(stones[stones.length - 1]).isEmpty();
    }
}

import java.util.*;

class Solution {
    public boolean canCross(int[] stones) {
        Set<Integer> stoneSet = new HashSet<>();
        for (int s : stones) stoneSet.add(s);
        int target = stones[stones.length - 1];
        Map<Long, Boolean> memo = new HashMap<>();
        return dfs(stoneSet, target, 0, 0, memo);
    }
    private boolean dfs(Set<Integer> stoneSet, int target, int pos, int lastJump, Map<Long, Boolean> memo) {
        if (pos == target) return true;
        long key = (long) pos * 100000L + lastJump;
        if (memo.containsKey(key)) return memo.get(key);
        boolean result = false;
        for (int jump = lastJump - 1; jump <= lastJump + 1; jump++) {
            if (jump > 0 && stoneSet.contains(pos + jump)) {
                if (dfs(stoneSet, target, pos + jump, jump, memo)) {
                    result = true;
                    break;
                }
            }
        }
        memo.put(key, result);
        return result;
    }
}
